/* ===== КОНФИГ — единственное место с именами таблиц и колонок ===== */
const cfg = {
  T_EVENT:   '<catalog>.<schema>.ta_event',           // журнал ЦА (создать, DDL в FLOW.md §2)
  T_OWNERS:  '<catalog>.<schema>.<dashboard_owners>', // dashboard_id, owner_login
  T_MDM:     '<catalog>.<schema>.mdm_employee_daily_proteus',
  T_ADGROUP: '<catalog>.<schema>.<ad_group_members>', // login, group_nm
  MDM_LOGIN: 'login',
  MDM_DT:    'report_dt',
  // Разрез → SQL-выражение над строкой mdm (алиас e), возвращает ТО ЖЕ название,
  // что показывает конструктор. adgroup считается через T_ADGROUP.
  DIM_EXPR: {
    lvl3:   'e.<lvl3_nm>',
    lvl4:   'e.<lvl4_nm>',
    stream: 'e.<stream_nm>',
    spec:   'e.<spec_nm>',
    exp:    "CASE WHEN date_diff('year', e.<hire_dt>, current_date) < 1 THEN 'до 1 года' WHEN date_diff('year', e.<hire_dt>, current_date) < 3 THEN '1–3 года' WHEN date_diff('year', e.<hire_dt>, current_date) < 5 THEN '3–5 лет' WHEN date_diff('year', e.<hire_dt>, current_date) < 10 THEN '5–10 лет' ELSE '10+ лет' END",
    it:     "CASE WHEN e.<it_flg> = 1 THEN 'IT' ELSE 'non-IT' END",
    hq:     "CASE WHEN e.<hq_flg> = 1 THEN 'HQ' ELSE 'non-HQ' END",
  },
};
/* ================================================================== */
const DIMS = ['lvl3', 'lvl4', 'stream', 'spec', 'exp', 'it', 'hq', 'adgroup'];
const MAX_VALUES = 200;
const b = $input.first().json.body || {};
const fail = (error, detail) => [{ json: { ok: false, status: 400, error, detail: detail || null } }];
const okStr = (s, max) => typeof s === 'string' && s.trim() && s.length <= max && !/[\u0000-\u001f]/.test(s);

if (!['save', 'deactivate'].includes(b.action)) return fail('bad_action');
if (!Number.isInteger(b.dashboard_id) || b.dashboard_id <= 0) return fail('bad_dashboard_id');
if (!okStr(b.request_id, 64) || !/^[A-Za-z0-9-]{8,64}$/.test(b.request_id)) return fail('bad_request_id');
if (!Number.isInteger(b.expected_version) || b.expected_version < 0) return fail('bad_expected_version');
// Логин — тот, что Proteus подставил из user_name авторизованного пользователя.
if (!okStr(b.login, 64) || !/^[A-Za-z0-9._-]+$/.test(b.login)) return [{ json: { ok: false, status: 401, error: 'no_login' } }];

const filters = {};
if (b.action === 'save') {
  const f = b.filters || {};
  const unknown = Object.keys(f).filter((k) => !DIMS.includes(k));
  if (unknown.length) return fail('unknown_dims', unknown);
  for (const k of DIMS) {
    const v = f[k] || [];
    if (!Array.isArray(v) || v.some((s) => !okStr(s, 200))) return fail('bad_values', k);
    if (v.length > MAX_VALUES) return fail('too_many_values', k);
    filters[k] = [...new Set(v.map((s) => s.trim()))].sort();
  }
  if (!DIMS.some((k) => filters[k].length)) return fail('no_conditions');
}
if (b.comment != null && typeof b.comment !== 'string') return fail('bad_comment');

return [{ json: {
  ok: true, cfg, DIMS,
  req: {
    action: b.action, dashboard_id: b.dashboard_id, request_id: b.request_id,
    expected_version: b.expected_version, filters,
    login: b.login.toLowerCase(),
    comment: String(b.comment || '').replace(/[\u0000-\u001f]/g, ' ').slice(0, 500),
    client: 'proteus_adoption_ui',
  },
  ctx: {},
} }];

// Строковый литерал Trino. Значения уже проверены в «Конфиг и валидация»,
// но экранируем всегда: SQL собирается из пользовательского ввода.
const q = (s) => "'" + String(s).replace(/'/g, "''") + "'";
const arr = (a) => (a.length ? 'ARRAY[' + a.map(q).join(', ') + ']' : 'CAST(ARRAY[] AS ARRAY(VARCHAR))');

const it = $input.first().json;
const sql = 'SELECT DISTINCT lower(owner_login) AS login FROM ' + it.cfg.T_OWNERS +
  ' WHERE dashboard_id = ' + it.req.dashboard_id;
return [{ json: { ...it, sql } }];

/* STUB → заменить на Execute Workflow «trino_query» (вход: {{ $json.sql }}).
   Выход подпроцесса: { rows: [{колонка: значение}], update_count: число|null }.
   Ниже — мок-ответ, чтобы флоу работал без Trino. */
const sql = $input.first().json.sql;
const id = Number((sql.match(/dashboard_id = (\d+)/) || [])[1]);
return [{ json: { rows: id >= 14000 && id <= 15000 ? [{ login: 'a.petrova' }, { login: 'd.sokolov' }] : [], update_count: null } }];

// Редактировать ЦА могут все владельцы отчёта, и только они.
const it = $('SQL: владельцы').first().json;
const owners = ($input.first().json.rows || []).map((r) => r.login);
if (!owners.length) return [{ json: { ok: false, status: 404, error: 'report_not_found' } }];
if (!owners.includes(it.req.login)) return [{ json: { ok: false, status: 403, error: 'not_owner', detail: { owners } } }];
const { sql, ...rest } = it;
return [{ json: { ...rest, ok: true, ctx: { ...it.ctx, owners } } }];

// Строковый литерал Trino. Значения уже проверены в «Конфиг и валидация»,
// но экранируем всегда: SQL собирается из пользовательского ввода.
const q = (s) => "'" + String(s).replace(/'/g, "''") + "'";
const arr = (a) => (a.length ? 'ARRAY[' + a.map(q).join(', ') + ']' : 'CAST(ARRAY[] AS ARRAY(VARCHAR))');

const it = $input.first().json;
// Одним запросом: последняя версия отчёта и, если есть, запись с тем же request_id.
const sql =
  'SELECT dashboard_id, version, action, saved_by, ' +
  "to_iso8601(saved_at) AS saved_at, request_id FROM " + it.cfg.T_EVENT +
  ' WHERE dashboard_id = ' + it.req.dashboard_id + ' OR request_id = ' + q(it.req.request_id) +
  ' ORDER BY version DESC';
return [{ json: { ...it, sql } }];

/* STUB → заменить на Execute Workflow «trino_query» (вход: {{ $json.sql }}).
   Выход подпроцесса: { rows: [{колонка: значение}], update_count: число|null }.
   Ниже — мок-ответ, чтобы флоу работал без Trino. */
const sql = $input.first().json.sql;
const id = Number((sql.match(/dashboard_id = (\d+)/) || [])[1]);
return [{ json: { rows: id === 14037
  ? [{ dashboard_id: 14037, version: 2, action: 'save', saved_by: 'd.sokolov', saved_at: '2026-10-12T09:14:00Z', request_id: 'old-req-0002' }]
  : [], update_count: null } }];

const it = $('SQL: текущая версия').first().json;
const rows = $input.first().json.rows || [];
const { sql, ...rest } = it;
// Идемпотентность: этот request_id уже записан — отвечаем тем же результатом.
const replay = rows.find((r) => r.request_id === it.req.request_id);
if (replay) return [{ json: { ok: false, status: 200, body: { ok: true, replay: true, dashboard_id: replay.dashboard_id,
  action: replay.action, version: replay.version, saved_by: replay.saved_by, saved_at: replay.saved_at } } }];
const current = rows.find((r) => r.dashboard_id === it.req.dashboard_id) || null;
const have = current ? Number(current.version) : 0;
if (it.req.expected_version !== have) {
  return [{ json: { ok: false, status: 409, error: 'version_conflict',
    detail: { current_version: have, saved_by: current && current.saved_by, saved_at: current && current.saved_at } } }];
}
if (it.req.action === 'deactivate' && (!current || current.action === 'deactivate')) {
  return [{ json: { ok: false, status: 409, error: 'nothing_to_deactivate' } }];
}
return [{ json: { ...rest, ok: true, ctx: { ...it.ctx, next_version: have + 1, audience_cnt: null } } }];

// Строковый литерал Trino. Значения уже проверены в «Конфиг и валидация»,
// но экранируем всегда: SQL собирается из пользовательского ввода.
const q = (s) => "'" + String(s).replace(/'/g, "''") + "'";
const arr = (a) => (a.length ? 'ARRAY[' + a.map(q).join(', ') + ']' : 'CAST(ARRAY[] AS ARRAY(VARCHAR))');

const it = $input.first().json;
const { cfg, DIMS } = it;
const f = it.req.filters;
const lastDt = cfg.MDM_DT + ' = (SELECT max(' + cfg.MDM_DT + ') FROM ' + cfg.T_MDM + ')';
const inList = (a) => '(' + a.map(q).join(', ') + ')';
const parts = [];
const preds = [];
DIMS.filter((k) => f[k].length).forEach((k) => {
  if (k === 'adgroup') {
    parts.push("SELECT DISTINCT 'adgroup' AS dim, group_nm AS val FROM " + cfg.T_ADGROUP + ' WHERE group_nm IN ' + inList(f[k]));
    preds.push('EXISTS (SELECT 1 FROM ' + cfg.T_ADGROUP + ' g WHERE lower(g.login) = lower(e.' + cfg.MDM_LOGIN + ') AND g.group_nm IN ' + inList(f[k]) + ')');
  } else {
    const ex = cfg.DIM_EXPR[k];
    parts.push('SELECT DISTINCT ' + q(k) + ' AS dim, ' + ex + ' AS val FROM ' + cfg.T_MDM + ' e WHERE e.' + lastDt + ' AND ' + ex + ' IN ' + inList(f[k]));
    preds.push(ex + ' IN ' + inList(f[k]));
  }
});
// Последняя строка — численность: dim='__count'. Внутри разреза ИЛИ (IN), между — И.
parts.push("SELECT '__count' AS dim, CAST(count(*) AS VARCHAR) AS val FROM " + cfg.T_MDM + ' e WHERE e.' + lastDt + ' AND ' + preds.join(' AND '));
return [{ json: { ...it, sql: parts.join('\nUNION ALL\n') } }];

/* STUB → заменить на Execute Workflow «trino_query» (вход: {{ $json.sql }}).
   Выход подпроцесса: { rows: [{колонка: значение}], update_count: число|null }.
   Ниже — мок-ответ, чтобы флоу работал без Trino. */
const sql = $input.first().json.sql;
// Мок: значение, начинающееся с «Старое», считается исчезнувшим из структуры.
const rows = [];
const re = /'([a-z0-9]+)' AS dim, .*? IN \(([^)]*)\)/g;
let m;
while ((m = re.exec(sql))) {
  const vals = m[2].split(', ').map((s) => s.slice(1, -1).replace(/''/g, "'"));
  vals.filter((v) => !v.startsWith('Старое')).forEach((v) => rows.push({ dim: m[1], val: v }));
}
const adg = sql.match(/'adgroup' AS dim, group_nm AS val FROM \S+ WHERE group_nm IN \(([^)]*)\)/);
if (adg) adg[1].split(', ').forEach((s) => rows.push({ dim: 'adgroup', val: s.slice(1, -1) }));
rows.push({ dim: '__count', val: sql.includes('Пустой') ? '0' : '1240' });
return [{ json: { rows, update_count: null } }];

const it = $('SQL: значения и численность').first().json;
const rows = $input.first().json.rows || [];
const { sql, ...rest } = it;
const found = {};
let cnt = 0;
rows.forEach((r) => { if (r.dim === '__count') cnt = Number(r.val); else (found[r.dim] = found[r.dim] || new Set()).add(r.val); });
const unknown = {};
it.DIMS.forEach((k) => {
  const miss = it.req.filters[k].filter((v) => !(found[k] && found[k].has(v)));
  if (miss.length) unknown[k] = miss;
});
if (Object.keys(unknown).length) return [{ json: { ok: false, status: 422, error: 'unknown_values', detail: unknown } }];
if (!cnt) return [{ json: { ok: false, status: 422, error: 'empty_audience' } }];
return [{ json: { ...rest, ok: true, ctx: { ...it.ctx, audience_cnt: cnt } } }];

// Строковый литерал Trino. Значения уже проверены в «Конфиг и валидация»,
// но экранируем всегда: SQL собирается из пользовательского ввода.
const q = (s) => "'" + String(s).replace(/'/g, "''") + "'";
const arr = (a) => (a.length ? 'ARRAY[' + a.map(q).join(', ') + ']' : 'CAST(ARRAY[] AS ARRAY(VARCHAR))');

const it = $input.first().json;
const { cfg, DIMS, req, ctx } = it;
const f = req.action === 'save' ? req.filters : {};
const savedAt = new Date().toISOString();
const row = {
  event_id: req.request_id + '-v' + ctx.next_version,
  request_id: req.request_id, dashboard_id: req.dashboard_id, action: req.action,
  version: ctx.next_version, audience_cnt: ctx.audience_cnt, comment: req.comment,
  saved_by: req.login, saved_at: savedAt, client: req.client,
};
DIMS.forEach((k) => { row['f_' + k] = f[k] || []; });
const cols = ['event_id', 'request_id', 'dashboard_id', 'action', 'version']
  .concat(DIMS.map((k) => 'f_' + k)).concat(['audience_cnt', 'comment', 'saved_by', 'saved_at', 'client']);
const lit = {
  event_id: q(row.event_id), request_id: q(row.request_id), dashboard_id: String(row.dashboard_id),
  action: q(row.action), version: String(row.version),
  audience_cnt: row.audience_cnt == null ? 'CAST(NULL AS INTEGER)' : String(row.audience_cnt),
  comment: q(row.comment), saved_by: q(row.saved_by),
  saved_at: 'from_iso8601_timestamp(' + q(savedAt) + ')', client: q(row.client),
};
DIMS.forEach((k) => { lit['f_' + k] = arr(row['f_' + k]); });
/* Условная вставка: пишем, только если версия не сдвинулась и request_id новый.
   Вставилось 0 строк → кто-то успел раньше → 409. */
const sql = 'INSERT INTO ' + cfg.T_EVENT + ' (' + cols.join(', ') + ')\n' +
  'SELECT ' + cols.map((c) => lit[c]).join(', ') + '\n' +
  'FROM (VALUES 1) AS t(x)\n' +
  'WHERE (SELECT coalesce(max(version), 0) FROM ' + cfg.T_EVENT + ' WHERE dashboard_id = ' + req.dashboard_id + ') = ' + req.expected_version + '\n' +
  '  AND NOT EXISTS (SELECT 1 FROM ' + cfg.T_EVENT + ' WHERE request_id = ' + q(req.request_id) + ')';
return [{ json: { ...it, row, sql } }];

/* STUB → заменить на Execute Workflow «trino_query» (вход: {{ $json.sql }}).
   Выход подпроцесса: { rows: [{колонка: значение}], update_count: число|null }.
   Ниже — мок-ответ, чтобы флоу работал без Trino. */
const sql = $input.first().json.sql;
return [{ json: { rows: [], update_count: 1 } }];

const it = $('SQL: запись события').first().json;
const n = $input.first().json.update_count;
if (n !== 1) return [{ json: { ok: false, status: 409, error: 'version_conflict', detail: { reason: 'concurrent_write' } } }];
return [{ json: { ok: true, status: 200, body: {
  ok: true, action: it.row.action, dashboard_id: it.row.dashboard_id, version: it.row.version,
  saved_by: it.row.saved_by, saved_at: it.row.saved_at, audience_cnt: it.row.audience_cnt,
  sync: 'scheduled',   // в ClickHouse появится после ближайшего запуска ноутбука
} } }];

// Все ветки «нет». Внутренности (cfg, sql, ctx) наружу не отдаём.
const it = $input.first().json;
if (it.body) return [{ json: { status: it.status, body: it.body } }];   // повтор request_id
return [{ json: { status: it.status || 500, body: { ok: false, error: it.error || 'internal', detail: it.detail || null } } }];
